        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90030003-0000-4000-8000-000000000001', 'On 14th July 1789, the agitated people of Paris stormed which fortress prison, symbolizing royal despotism?', '{"A":"Bastille","B":"Tuileries","C":"Versailles","D":"Louvre"}'::jsonb, 'A', 'MCQ', 'Social Science', 'The French Revolution', 1, NULL, NULL, NULL, 'The storming of the Bastille on July 14, 1789, marked the dramatic outbreak of the French Revolution against Louis XVI''s autocratic rule.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000002', 'Who was the leader of the Bolshevik party in Russia during the 1917 October Revolution?', '{"A":"Karl Marx","B":"Vladimir Lenin","C":"Joseph Stalin","D":"Leon Trotsky"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Socialism in Europe and the Russian Revolution', 1, NULL, NULL, NULL, 'Vladimir Lenin returned from exile and led the Bolsheviks to overthrow the Provisional Government in October 1917.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000003', 'The infamous ''Enabling Act'' passed on 3rd March 1933 in Germany allowed Hitler to:', '{"A":"Declare war on Britain","B":"Establish dictatorship and rule by decree without parliament","C":"Abolish the Nazi party","D":"Form the Weimar Republic"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nazism and the Rise of Hitler', 1, NULL, NULL, NULL, 'The Enabling Act suspended civil liberties, bypassed the Reichstag, and established Hitler''s dictatorial totalitarian rule.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000004', 'The Standard Meridian of India (82°30'' E) passes through which of the following cities in Uttar Pradesh?', '{"A":"Mirzapur","B":"Lucknow","C":"Kanpur","D":"Varanasi"}'::jsonb, 'A', 'MCQ', 'Social Science', 'India - Size and Location', 1, NULL, NULL, NULL, 'The 82°30'' E longitude passing through Mirzapur (near Prayagraj) is adopted as the Indian Standard Time (IST) meridian.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000005', 'Which parallel of latitude divides India into almost two equal halves?', '{"A":"Equator","B":"Tropic of Cancer (23°30'' N)","C":"Tropic of Capricorn (23°30'' S)","D":"Arctic Circle"}'::jsonb, 'B', 'MCQ', 'Social Science', 'India - Size and Location', 1, NULL, NULL, NULL, 'The Tropic of Cancer at 23°30'' N latitude passes through eight Indian states, dividing the country into subtropical and tropical zones.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000006', 'The northernmost range of the Himalayas, known for its lofty peaks and perennial snow cover, is called:', '{"A":"Himadri (Inner Himalayas)","B":"Himachal (Lesser Himalayas)","C":"Shiwaliks (Outer Himalayas)","D":"Purvanchal"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Physical Features of India', 1, NULL, NULL, NULL, 'The Great or Inner Himalayas, also known as Himadri, has an average elevation of 6,000 meters and contains the highest peaks.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000007', 'Which river originates from the Chemayungdung glacier near Lake Mansarovar in Tibet and is locally known as Tsangpo?', '{"A":"Ganga","B":"Indus","C":"Brahmaputra","D":"Yamuna"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Drainage', 1, NULL, NULL, NULL, 'The Brahmaputra rises in Tibet east of Lake Mansarovar as the Tsangpo and enters India in Arunachal Pradesh as the Dihang.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000008', 'The seasonal reversal in wind direction during the year over the Indian subcontinent is called:', '{"A":"Trade winds","B":"Monsoon","C":"Loo","D":"Jet stream"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Climate', 1, NULL, NULL, NULL, 'The word ''Monsoon'' is derived from the Arabic word ''Mausim'', meaning season, indicating periodic wind reversal.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000009', 'In a democracy, the final decision-making power must rest with:', '{"A":"The military commanders","B":"The monarch","C":"Those elected by the citizens","D":"The judiciary solely"}'::jsonb, 'C', 'MCQ', 'Social Science', 'What is Democracy? Why Democracy?', 1, NULL, NULL, NULL, 'A core principle of representative democracy is that supreme decision-making authority rests with elected representatives of the people.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-00000000000a', 'Who was the Chairman of the Drafting Committee of the Indian Constituent Assembly?', '{"A":"Dr. B.R. Ambedkar","B":"Dr. Rajendra Prasad","C":"Jawaharlal Nehru","D":"Sardar Vallabhbhai Patel"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Constitutional Design', 1, NULL, NULL, NULL, 'Dr. Bhimrao Ramji Ambedkar chaired the Drafting Committee that prepared the final Draft Constitution of independent India.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-00000000000b', 'In India, elections to the Lok Sabha and State Legislative Assemblies are held regularly every:', '{"A":"4 years","B":"5 years","C":"6 years","D":"3 years"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Electoral Politics', 1, NULL, NULL, NULL, 'Under Article 83 and 172 of the Indian Constitution, the normal tenure of Lok Sabha and Vidhan Sabhas is five years.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-00000000000c', 'Which of the following is considered the working capital in a farming enterprise?', '{"A":"Tractor and harvesters","B":"Tubewell and irrigation pipes","C":"Raw seeds, fertilizers, and cash in hand","D":"Farm building"}'::jsonb, 'C', 'MCQ', 'Social Science', 'People as Resource', 1, NULL, NULL, NULL, 'Working capital includes materials and money that are consumed and used up in the production cycle, such as seeds, chemical fertilizers, and liquid cash.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-00000000000d', 'Investment in human capital formation through education and healthcare yield returns in the form of:', '{"A":"Higher earning capacity and greater social productivity","B":"Depreciation of physical capital","C":"Lower tax revenues","D":"Decreased longevity"}'::jsonb, 'A', 'MCQ', 'Social Science', 'People as Resource', 1, NULL, NULL, NULL, 'Human capital investment enhances labor productivity, skills, health status, and economic innovation, yielding substantial lifelong returns.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-00000000000e', 'Which organization conducts periodic sample surveys for estimating the poverty line in India?', '{"A":"National Sample Survey Office (NSSO / NSO)","B":"Reserve Bank of India","C":"Finance Ministry","D":"NITI Aayog solely"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Poverty as a Challenge', 1, NULL, NULL, NULL, 'The National Sample Survey Office (under Ministry of Statistics and Programme Implementation) conducts periodic quinquennial surveys for poverty estimation.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-00000000000f', 'Under the Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA 2005), guaranteed wage employment is provided for at least:', '{"A":"50 days","B":"100 days","C":"150 days","D":"200 days"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Poverty as a Challenge', 1, NULL, NULL, NULL, 'MGNREGA provides a legal guarantee for 100 days of unskilled wage employment per financial year to every rural household whose adult members volunteer.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000010', 'The delta formed by the Ganga and Brahmaputra rivers, known for Sundari mangrove trees, is:', '{"A":"Mahanadi delta","B":"Sundarbans delta","C":"Godavari delta","D":"Kaveri delta"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Drainage', 1, NULL, NULL, NULL, 'The Sundarbans delta is the world''s largest and fastest-growing mangrove delta, named after the native Sundari mangrove tree.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000011', 'Which state of India receives rainfall from the North-East retreating monsoons during October and November?', '{"A":"Punjab","B":"Tamil Nadu","C":"Rajasthan","D":"Maharashtra"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Climate', 1, NULL, NULL, NULL, 'The retreating monsoon winds pick up moisture over the Bay of Bengal and bring substantial cyclonic rain to the Coromandel Coast of Tamil Nadu.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000012', 'The term ''Universal Adult Franchise'' implies that:', '{"A":"Only property owners can vote","B":"Every adult citizen of 18 years or above has one vote with equal value","C":"Only educated men can vote","D":"Only taxpayers can contest"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Electoral Politics', 1, NULL, NULL, NULL, 'Universal adult franchise grants every citizen who is at least 18 years old the constitutional right to cast one vote, where each vote carries equal weight.', 'MEDIUM', true),
        ('90030003-0000-4000-8000-000000000013', 'Assertion (A): The Himalayas act as an effective climatic divide for the Indian subcontinent.
