        ('9003000b-0000-4000-8000-00000000000c', 'Which of the following is considered the working capital in a farming enterprise?', '{"A":"Tractor and harvesters","B":"Tubewell and irrigation pipes","C":"Raw seeds, fertilizers, and cash in hand","D":"Farm building"}'::jsonb, 'C', 'MCQ', 'Social Science', 'People as Resource', 1, NULL, NULL, NULL, 'Working capital includes materials and money that are consumed and used up in the production cycle, such as seeds, chemical fertilizers, and liquid cash.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-00000000000d', 'Investment in human capital formation through education and healthcare yield returns in the form of:', '{"A":"Higher earning capacity and greater social productivity","B":"Depreciation of physical capital","C":"Lower tax revenues","D":"Decreased longevity"}'::jsonb, 'A', 'MCQ', 'Social Science', 'People as Resource', 1, NULL, NULL, NULL, 'Human capital investment enhances labor productivity, skills, health status, and economic innovation, yielding substantial lifelong returns.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-00000000000e', 'Which organization conducts periodic sample surveys for estimating the poverty line in India?', '{"A":"National Sample Survey Office (NSSO / NSO)","B":"Reserve Bank of India","C":"Finance Ministry","D":"NITI Aayog solely"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Poverty as a Challenge', 1, NULL, NULL, NULL, 'The National Sample Survey Office (under Ministry of Statistics and Programme Implementation) conducts periodic quinquennial surveys for poverty estimation.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-00000000000f', 'Under the Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA 2005), guaranteed wage employment is provided for at least:', '{"A":"50 days","B":"100 days","C":"150 days","D":"200 days"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Poverty as a Challenge', 1, NULL, NULL, NULL, 'MGNREGA provides a legal guarantee for 100 days of unskilled wage employment per financial year to every rural household whose adult members volunteer.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-000000000010', 'The delta formed by the Ganga and Brahmaputra rivers, known for Sundari mangrove trees, is:', '{"A":"Mahanadi delta","B":"Sundarbans delta","C":"Godavari delta","D":"Kaveri delta"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Drainage', 1, NULL, NULL, NULL, 'The Sundarbans delta is the world''s largest and fastest-growing mangrove delta, named after the native Sundari mangrove tree.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-000000000011', 'Which state of India receives rainfall from the North-East retreating monsoons during October and November?', '{"A":"Punjab","B":"Tamil Nadu","C":"Rajasthan","D":"Maharashtra"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Climate', 1, NULL, NULL, NULL, 'The retreating monsoon winds pick up moisture over the Bay of Bengal and bring substantial cyclonic rain to the Coromandel Coast of Tamil Nadu.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-000000000012', 'The term ''Universal Adult Franchise'' implies that:', '{"A":"Only property owners can vote","B":"Every adult citizen of 18 years or above has one vote with equal value","C":"Only educated men can vote","D":"Only taxpayers can contest"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Electoral Politics', 1, NULL, NULL, NULL, 'Universal adult franchise grants every citizen who is at least 18 years old the constitutional right to cast one vote, where each vote carries equal weight.', 'MEDIUM', true),
        ('9003000b-0000-4000-8000-000000000013', 'Assertion (A): The Himalayas act as an effective climatic divide for the Indian subcontinent.
