        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90030016-0000-4000-8000-000000000001', 'On 14th July 1789, the agitated people of Paris stormed which fortress prison, symbolizing royal despotism?', '{"A":"Bastille","B":"Tuileries","C":"Versailles","D":"Louvre"}'::jsonb, 'A', 'MCQ', 'Social Science', 'The French Revolution', 1, NULL, NULL, NULL, 'The storming of the Bastille on July 14, 1789, marked the dramatic outbreak of the French Revolution against Louis XVI''s autocratic rule.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000002', 'Who was the leader of the Bolshevik party in Russia during the 1917 October Revolution?', '{"A":"Karl Marx","B":"Vladimir Lenin","C":"Joseph Stalin","D":"Leon Trotsky"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Socialism in Europe and the Russian Revolution', 1, NULL, NULL, NULL, 'Vladimir Lenin returned from exile and led the Bolsheviks to overthrow the Provisional Government in October 1917.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000003', 'The infamous ''Enabling Act'' passed on 3rd March 1933 in Germany allowed Hitler to:', '{"A":"Declare war on Britain","B":"Establish dictatorship and rule by decree without parliament","C":"Abolish the Nazi party","D":"Form the Weimar Republic"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nazism and the Rise of Hitler', 1, NULL, NULL, NULL, 'The Enabling Act suspended civil liberties, bypassed the Reichstag, and established Hitler''s dictatorial totalitarian rule.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000004', 'The Standard Meridian of India (82°30'' E) passes through which of the following cities in Uttar Pradesh?', '{"A":"Mirzapur","B":"Lucknow","C":"Kanpur","D":"Varanasi"}'::jsonb, 'A', 'MCQ', 'Social Science', 'India - Size and Location', 1, NULL, NULL, NULL, 'The 82°30'' E longitude passing through Mirzapur (near Prayagraj) is adopted as the Indian Standard Time (IST) meridian.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000005', 'Which parallel of latitude divides India into almost two equal halves?', '{"A":"Equator","B":"Tropic of Cancer (23°30'' N)","C":"Tropic of Capricorn (23°30'' S)","D":"Arctic Circle"}'::jsonb, 'B', 'MCQ', 'Social Science', 'India - Size and Location', 1, NULL, NULL, NULL, 'The Tropic of Cancer at 23°30'' N latitude passes through eight Indian states, dividing the country into subtropical and tropical zones.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000006', 'The northernmost range of the Himalayas, known for its lofty peaks and perennial snow cover, is called:', '{"A":"Himadri (Inner Himalayas)","B":"Himachal (Lesser Himalayas)","C":"Shiwaliks (Outer Himalayas)","D":"Purvanchal"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Physical Features of India', 1, NULL, NULL, NULL, 'The Great or Inner Himalayas, also known as Himadri, has an average elevation of 6,000 meters and contains the highest peaks.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000007', 'Which river originates from the Chemayungdung glacier near Lake Mansarovar in Tibet and is locally known as Tsangpo?', '{"A":"Ganga","B":"Indus","C":"Brahmaputra","D":"Yamuna"}'::jsonb, 'C', 'MCQ', 'Social Science', 'Drainage', 1, NULL, NULL, NULL, 'The Brahmaputra rises in Tibet east of Lake Mansarovar as the Tsangpo and enters India in Arunachal Pradesh as the Dihang.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000008', 'The seasonal reversal in wind direction during the year over the Indian subcontinent is called:', '{"A":"Trade winds","B":"Monsoon","C":"Loo","D":"Jet stream"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Climate', 1, NULL, NULL, NULL, 'The word ''Monsoon'' is derived from the Arabic word ''Mausim'', meaning season, indicating periodic wind reversal.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000009', 'In a democracy, the final decision-making power must rest with:', '{"A":"The military commanders","B":"The monarch","C":"Those elected by the citizens","D":"The judiciary solely"}'::jsonb, 'C', 'MCQ', 'Social Science', 'What is Democracy? Why Democracy?', 1, NULL, NULL, NULL, 'A core principle of representative democracy is that supreme decision-making authority rests with elected representatives of the people.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-00000000000a', 'Who was the Chairman of the Drafting Committee of the Indian Constituent Assembly?', '{"A":"Dr. B.R. Ambedkar","B":"Dr. Rajendra Prasad","C":"Jawaharlal Nehru","D":"Sardar Vallabhbhai Patel"}'::jsonb, 'A', 'MCQ', 'Social Science', 'Constitutional Design', 1, NULL, NULL, NULL, 'Dr. Bhimrao Ramji Ambedkar chaired the Drafting Committee that prepared the final Draft Constitution of independent India.', 'MEDIUM', true),
        ('90030016-0000-4000-8000-00000000000b', 'What were the three estates in 18th-century French society? Which estate paid all the taxes?', NULL, NULL, 'VSA', 'Social Science', 'The French Revolution', 2, 'The three estates were: First Estate (Clergy), Second Estate (Nobility), and Third Estate (Big businessmen, merchants, court officials, lawyers, peasants, and landless artisans). Only the Third Estate paid all direct and indirect taxes (Taille and Tithe).', '1 Mark for listing the 3 estates correctly; 1 Mark for specifying that the Third Estate bore all taxes', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-00000000000c', 'What is the ''Preamble'' to the Indian Constitution? State any two core democratic values enshrined in it.', NULL, NULL, 'VSA', 'Social Science', 'Constitutional Design', 2, 'The Preamble is an introductory guiding statement that sets out the guiding purposes, principles, and philosophy of the Constitution. Core values: Sovereign, Socialist, Secular, Democratic, Republic, Justice, Liberty, Equality, and Fraternity (any two).', '1 Mark for definition of Preamble; 1 Mark for mentioning two core values with brief context', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-00000000000d', 'Explain any three major demands made by Vladimir Lenin in his famous ''April Theses'' of 1917.', NULL, NULL, 'SA', 'Social Science', 'Socialism in Europe and the Russian Revolution', 3, 'In April 1917, Bolshevik leader Vladimir Lenin returned to Russia and put forward three urgent demands known as April Theses: 1. The ongoing First World War must be brought to an immediate close. 2. All land owned by the nobility and clergy must be transferred to the peasants. 3. All banks must be nationalized under state control.', '1 Mark for end of World War I; 1 Mark for transfer of land to peasants; 1 Mark for nationalization of banks', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-00000000000e', 'Describe the three Himalayan river systems that form the northern plains of India and state two characteristics of their drainage.', NULL, NULL, 'SA', 'Social Science', 'Drainage', 3, 'The three river systems are: 1. The Indus River System, 2. The Ganga River System, 3. The Brahmaputra River System. Characteristics: (i) They are perennial rivers fed by both rainfall and melting Himalayan snow. (ii) In their upper courses, they perform intensive erosional action forming deep gorges, while in lower courses they create floodplains, meanders, and expansive deltas.', '1 Mark for naming the three river systems; 2 Marks for two distinct hydrological characteristics (perennial flow and depositional landforms)', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-00000000000f', 'Why is an independent and impartial judiciary essential in a constitutional democracy like India?', NULL, NULL, 'SA', 'Social Science', 'Constitutional Design', 3, 'An independent judiciary is vital because: 1. Protector of Fundamental Rights: Citizens can approach courts (High Courts and Supreme Court) under Articles 32 and 226 if rights are infringed. 2. Guardian of the Constitution: It has the power of Judicial Review to strike down unconstitutional executive orders and parliamentary laws. 3. Dispute Resolution: It resolves legal disputes between center and states or between citizens and the state impartially.', '1 Mark for protection of Fundamental Rights; 1 Mark for Judicial Review; 1 Mark for federal dispute settlement', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000010', '(a) What were the primary social, economic, and political causes of the French Revolution of 1789? (b) How did the Declaration of the Rights of Man and Citizen transform French society?', NULL, NULL, 'LA', 'Social Science', 'The French Revolution', 5, '(a) Causes: 1. Political: Autocratic rule of Louis XVI, administrative corruption, and financial bankruptcy due to involvement in American Revolutionary War. 2. Social: Division into three estates where privileged first two estates enjoyed tax exemptions, while the third estate was oppressed. 3. Economic: Population explosion, crop failures, and rising price of bread causing subsistence crises. (b) Transformational impact: The Declaration established equality before the law, freedom of speech and press, religious toleration, and popular sovereignty, replacing divine right monarchy with the ideals of Liberty, Equality, and Fraternity.', '3 Marks for analyzing political, social, and economic causes; 2 Marks for evaluating the Declaration of the Rights of Man', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000011', '(a) Explain any three major powers of the Prime Minister of India. (b) Why is the Council of Ministers collectively responsible to the Lok Sabha?', NULL, NULL, 'LA', 'Social Science', 'What is Democracy? Why Democracy?', 5, '(a) Powers of the Prime Minister: 1. Leader of the Government: Presides over Cabinet meetings, coordinates work of departments, and makes major national policy decisions. 2. Allocation of Portfolios: Advises the President on appointing ministers and allocates or redistributes departmental portfolios. 3. Link to President: Serves as the chief communicator between the Council of Ministers and the President of India. (b) Collective Responsibility: Under Article 75(3), all ministers sink and swim together. If a Vote of No-Confidence is passed against the Prime Minister or Government in the Lok Sabha, the entire Council of Ministers must resign immediately, ensuring democratic accountability to the elected representatives.', '3 Marks for three distinct powers of Prime Minister; 2 Marks for constitutional mechanism of collective responsibility', NULL, NULL, 'MEDIUM', true),
        ('90030016-0000-4000-8000-000000000012', 'Answer the following: (i) What was the main objective of the French Constitution of 1791? (ii) What are ''natural and inalienable rights''? Name any two such rights mentioned in the text. (iii) How did the 1791 Constitution distinguish between ''active citizens'' and ''passive citizens''?', NULL, NULL, 'CASE', 'Social Science', 'The French Revolution', 4, '(i) The main objective was to establish a constitutional monarchy by limiting the absolute powers of the king and assigning them to separated legislative, executive, and judicial branches. (ii) Natural and inalienable rights belong to each human being by birth and cannot be taken away by state laws (e.g., Right to life, freedom of speech). (iii) Active citizens were men above 25 years who paid taxes equal to at least 3 days of a laborer''s wage and had voting rights. Passive citizens (remaining men and all women) were deprived of voting rights.', '1 Mark for constitutional monarchy objective; 1.5 Marks for natural rights and two examples; 1.5 Marks for active vs passive citizen distinction', 'In 1791, the National Assembly completed the draft of the French Constitution to limit the powers of the monarch. Powers were separated among legislature, executive, and judiciary. The Constitution began with a Declaration of the Rights of Man and Citizen, proclaiming natural and inalienable rights such as the right to life, freedom of speech, freedom of opinion, and equality before the law.', NULL, 'MEDIUM', true)
