        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90030021-0000-4000-8000-000000000001', 'On 14th July 1789, the agitated people of Paris stormed which fortress prison, symbolizing royal despotism?', '{"A":"Bastille","B":"Tuileries","C":"Versailles","D":"Louvre"}'::jsonb, 'A', 'MCQ', 'Social Science', 'The French Revolution', 1, NULL, NULL, NULL, 'The storming of the Bastille on July 14, 1789, marked the dramatic outbreak of the French Revolution against Louis XVI''s autocratic rule.', 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000002', 'Who was the leader of the Bolshevik party in Russia during the 1917 October Revolution?', '{"A":"Karl Marx","B":"Vladimir Lenin","C":"Joseph Stalin","D":"Leon Trotsky"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Socialism in Europe and the Russian Revolution', 1, NULL, NULL, NULL, 'Vladimir Lenin returned from exile and led the Bolsheviks to overthrow the Provisional Government in October 1917.', 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000003', 'The infamous ''Enabling Act'' passed on 3rd March 1933 in Germany allowed Hitler to:', '{"A":"Declare war on Britain","B":"Establish dictatorship and rule by decree without parliament","C":"Abolish the Nazi party","D":"Form the Weimar Republic"}'::jsonb, 'B', 'MCQ', 'Social Science', 'Nazism and the Rise of Hitler', 1, NULL, NULL, NULL, 'The Enabling Act suspended civil liberties, bypassed the Reichstag, and established Hitler''s dictatorial totalitarian rule.', 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000004', 'The Standard Meridian of India (82°30'' E) passes through which of the following cities in Uttar Pradesh?', '{"A":"Mirzapur","B":"Lucknow","C":"Kanpur","D":"Varanasi"}'::jsonb, 'A', 'MCQ', 'Social Science', 'India - Size and Location', 1, NULL, NULL, NULL, 'The 82°30'' E longitude passing through Mirzapur (near Prayagraj) is adopted as the Indian Standard Time (IST) meridian.', 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000005', 'Which parallel of latitude divides India into almost two equal halves?', '{"A":"Equator","B":"Tropic of Cancer (23°30'' N)","C":"Tropic of Capricorn (23°30'' S)","D":"Arctic Circle"}'::jsonb, 'B', 'MCQ', 'Social Science', 'India - Size and Location', 1, NULL, NULL, NULL, 'The Tropic of Cancer at 23°30'' N latitude passes through eight Indian states, dividing the country into subtropical and tropical zones.', 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000006', 'What were the three estates in 18th-century French society? Which estate paid all the taxes?', NULL, NULL, 'VSA', 'Social Science', 'The French Revolution', 2, 'The three estates were: First Estate (Clergy), Second Estate (Nobility), and Third Estate (Big businessmen, merchants, court officials, lawyers, peasants, and landless artisans). Only the Third Estate paid all direct and indirect taxes (Taille and Tithe).', '1 Mark for listing the 3 estates correctly; 1 Mark for specifying that the Third Estate bore all taxes', NULL, NULL, 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000007', 'What is the ''Preamble'' to the Indian Constitution? State any two core democratic values enshrined in it.', NULL, NULL, 'VSA', 'Social Science', 'Constitutional Design', 2, 'The Preamble is an introductory guiding statement that sets out the guiding purposes, principles, and philosophy of the Constitution. Core values: Sovereign, Socialist, Secular, Democratic, Republic, Justice, Liberty, Equality, and Fraternity (any two).', '1 Mark for definition of Preamble; 1 Mark for mentioning two core values with brief context', NULL, NULL, 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000008', 'Explain any three major demands made by Vladimir Lenin in his famous ''April Theses'' of 1917.', NULL, NULL, 'SA', 'Social Science', 'Socialism in Europe and the Russian Revolution', 3, 'In April 1917, Bolshevik leader Vladimir Lenin returned to Russia and put forward three urgent demands known as April Theses: 1. The ongoing First World War must be brought to an immediate close. 2. All land owned by the nobility and clergy must be transferred to the peasants. 3. All banks must be nationalized under state control.', '1 Mark for end of World War I; 1 Mark for transfer of land to peasants; 1 Mark for nationalization of banks', NULL, NULL, 'MEDIUM', true),
        ('90030021-0000-4000-8000-000000000009', 'Describe the three Himalayan river systems that form the northern plains of India and state two characteristics of their drainage.', NULL, NULL, 'SA', 'Social Science', 'Drainage', 3, 'The three river systems are: 1. The Indus River System, 2. The Ganga River System, 3. The Brahmaputra River System. Characteristics: (i) They are perennial rivers fed by both rainfall and melting Himalayan snow. (ii) In their upper courses, they perform intensive erosional action forming deep gorges, while in lower courses they create floodplains, meanders, and expansive deltas.', '1 Mark for naming the three river systems; 2 Marks for two distinct hydrological characteristics (perennial flow and depositional landforms)', NULL, NULL, 'MEDIUM', true),
        ('90030021-0000-4000-8000-00000000000a', '(a) Explain any three major powers of the Prime Minister of India. (b) Why is the Council of Ministers collectively responsible to the Lok Sabha?', NULL, NULL, 'LA', 'Social Science', 'What is Democracy? Why Democracy?', 5, '(a) Powers of the Prime Minister: 1. Leader of the Government: Presides over Cabinet meetings, coordinates work of departments, and makes major national policy decisions. 2. Allocation of Portfolios: Advises the President on appointing ministers and allocates or redistributes departmental portfolios. 3. Link to President: Serves as the chief communicator between the Council of Ministers and the President of India. (b) Collective Responsibility: Under Article 75(3), all ministers sink and swim together. If a Vote of No-Confidence is passed against the Prime Minister or Government in the Lok Sabha, the entire Council of Ministers must resign immediately, ensuring democratic accountability to the elected representatives.', '3 Marks for three distinct powers of Prime Minister; 2 Marks for constitutional mechanism of collective responsibility', NULL, NULL, 'MEDIUM', true)
