        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('90030032-0000-4000-8000-000000000001', 'Based on the passage, answer: (i) State any two constitutional safeguards that guarantee the independence of the Election Commission of India. (ii) What is the Model Code of Conduct (MCC)? (iii) Why is an independent election conducting body essential for free and fair democracy?', NULL, NULL, 'CASE', 'Social Science', 'Electoral Politics', 4, '(i) Safeguards: 1. Security of tenure: The CEC cannot be removed from office except by impeachment in Parliament similar to a Supreme Court judge. 2. Non-subordination: The ECI is not answerable to the government or executive during the election process. (ii) MCC is a set of mutually agreed norms and guidelines for political parties and candidates regarding speeches, rallies, polling conduct, and forbidding misuse of official government power. (iii) It guarantees that elections are free, impartial, and credible, ensuring that the ruling regime cannot manipulate voters or administrative levers.', '1.5 Marks for constitutional independence safeguards; 1 Mark for MCC definition; 1.5 Marks for necessity of free and fair electoral competition', 'Elections in India are democratic exercises of colossal scale conducted by the independent Election Commission of India (ECI). The Chief Election Commissioner (CEC) is appointed by the President but cannot be removed easily. During election periods, the ECI enforces the Model Code of Conduct (MCC) to ensure a level playing field, preventing the ruling party from misusing official government machinery, vehicles, or advertising funds.', NULL, 'MEDIUM', true),
        ('90030032-0000-4000-8000-000000000002', 'Answer the following: (i) What was the main objective of the French Constitution of 1791? (ii) What are ''natural and inalienable rights''? Name any two such rights mentioned in the text. (iii) How did the 1791 Constitution distinguish between ''active citizens'' and ''passive citizens''?', NULL, NULL, 'CASE', 'Social Science', 'The French Revolution', 4, '(i) The main objective was to establish a constitutional monarchy by limiting the absolute powers of the king and assigning them to separated legislative, executive, and judicial branches. (ii) Natural and inalienable rights belong to each human being by birth and cannot be taken away by state laws (e.g., Right to life, freedom of speech). (iii) Active citizens were men above 25 years who paid taxes equal to at least 3 days of a laborer''s wage and had voting rights. Passive citizens (remaining men and all women) were deprived of voting rights.', '1 Mark for constitutional monarchy objective; 1.5 Marks for natural rights and two examples; 1.5 Marks for active vs passive citizen distinction', 'In 1791, the National Assembly completed the draft of the French Constitution to limit the powers of the monarch. Powers were separated among legislature, executive, and judiciary. The Constitution began with a Declaration of the Rights of Man and Citizen, proclaiming natural and inalienable rights such as the right to life, freedom of speech, freedom of opinion, and equality before the law.', NULL, 'MEDIUM', true),
        ('90030032-0000-4000-8000-000000000003', 'Refer to the text and answer: (i) How was the Peninsular Plateau of India formed? (ii) Name the two broad divisions of the Peninsular Plateau separated by the Narmada river. (iii) Why is the peninsular plateau of immense economic importance to India?', NULL, NULL, 'CASE', 'Social Science', 'Physical Features of India', 4, '(i) The Peninsular Plateau was formed due to the breaking and drifting of the ancient Gondwana supercontinent, making it one of the oldest and most stable landmasses on Earth. (ii) The two divisions are: Central Highlands (north of the Narmada) and Deccan Plateau (south of the Narmada). (iii) Economic importance: 1. Storehouse of minerals: Contains huge reserves of iron ore, coal, bauxite, and mica. 2. Black soil (regur) in Deccan trap ideal for cotton cultivation. 3. Waterfall sites provide immense hydroelectric potential.', '1 Mark for Gondwana origin; 1 Mark for Central Highlands & Deccan Plateau; 2 Marks for minerals, black soil, and economic significance', 'India is endowed with diverse physical relief features resulting from tectonic plate movements. The peninsular plateau is an ancient landmass formed by breaking and drifting of the Gondwana continent. It consists of two broad divisions: the Central Highlands and the Deccan Plateau. The plateau is rich in valuable mineral deposits like iron ore, coal, and bauxite, while its black cotton soil (regur) supports prolific agriculture.', NULL, 'MEDIUM', true),
        ('90030032-0000-4000-8000-000000000004', 'Based on the passage, answer: (i) State any two constitutional safeguards that guarantee the independence of the Election Commission of India. (ii) What is the Model Code of Conduct (MCC)? (iii) Why is an independent election conducting body essential for free and fair democracy?', NULL, NULL, 'CASE', 'Social Science', 'Electoral Politics', 4, '(i) Safeguards: 1. Security of tenure: The CEC cannot be removed from office except by impeachment in Parliament similar to a Supreme Court judge. 2. Non-subordination: The ECI is not answerable to the government or executive during the election process. (ii) MCC is a set of mutually agreed norms and guidelines for political parties and candidates regarding speeches, rallies, polling conduct, and forbidding misuse of official government power. (iii) It guarantees that elections are free, impartial, and credible, ensuring that the ruling regime cannot manipulate voters or administrative levers.', '1.5 Marks for constitutional independence safeguards; 1 Mark for MCC definition; 1.5 Marks for necessity of free and fair electoral competition', 'Elections in India are democratic exercises of colossal scale conducted by the independent Election Commission of India (ECI). The Chief Election Commissioner (CEC) is appointed by the President but cannot be removed easily. During election periods, the ECI enforces the Model Code of Conduct (MCC) to ensure a level playing field, preventing the ruling party from misusing official government machinery, vehicles, or advertising funds.', NULL, 'MEDIUM', true),
        ('90030032-0000-4000-8000-000000000005', 'Answer the following: (i) What was the main objective of the French Constitution of 1791? (ii) What are ''natural and inalienable rights''? Name any two such rights mentioned in the text. (iii) How did the 1791 Constitution distinguish between ''active citizens'' and ''passive citizens''?', NULL, NULL, 'CASE', 'Social Science', 'The French Revolution', 4, '(i) The main objective was to establish a constitutional monarchy by limiting the absolute powers of the king and assigning them to separated legislative, executive, and judicial branches. (ii) Natural and inalienable rights belong to each human being by birth and cannot be taken away by state laws (e.g., Right to life, freedom of speech). (iii) Active citizens were men above 25 years who paid taxes equal to at least 3 days of a laborer''s wage and had voting rights. Passive citizens (remaining men and all women) were deprived of voting rights.', '1 Mark for constitutional monarchy objective; 1.5 Marks for natural rights and two examples; 1.5 Marks for active vs passive citizen distinction', 'In 1791, the National Assembly completed the draft of the French Constitution to limit the powers of the monarch. Powers were separated among legislature, executive, and judiciary. The Constitution began with a Declaration of the Rights of Man and Citizen, proclaiming natural and inalienable rights such as the right to life, freedom of speech, freedom of opinion, and equality before the law.', NULL, 'MEDIUM', true)
